def exponential_moving_average(ema_prev, x, alpha):
    return alpha * x + (1.0 - alpha) * ema_prev



def exponential_moving_variance(emv_prev, ema_prev, x, alpha):
    diff = x - ema_prev
    return (1.0 - alpha) * (emv_prev + alpha * diff * diff)



def river_sgd_update(weight, gradient, lr):
    return weight - lr * gradient



def perceptron_update(weight, x, y_true, y_pred, lr):
    return weight + lr * (y_true - y_pred) * x



def passive_aggressive_step(loss, x_norm_sq, c):
    if x_norm_sq <= 0.0:
        return 0.0
    tau = loss / x_norm_sq
    if tau > c:
        return c
    return tau



def adagrad_online_update(weight, gradient, accumulated_sq, lr, eps):
    new_acc = accumulated_sq + gradient * gradient
    return weight - lr * gradient / math.sqrt(new_acc + eps)



def ftrl_step(z, n, alpha, beta, l1, l2):
    abs_z = z if z >= 0.0 else -z
    if abs_z <= l1:
        return 0.0
    sign_z = 1.0 if z > 0.0 else -1.0
    denom = l2 + (beta + math.sqrt(n)) / alpha
    if denom == 0.0:
        return 0.0
    return -(z - sign_z * l1) / denom



def streaming_mean_update(mean, x, count):
    if count <= 0.0:
        return x
    return mean + (x - mean) / count



def streaming_variance_update(m2, old_mean, new_mean, x):
    return m2 + (x - old_mean) * (x - new_mean)



def concept_drift_ddm_error(error_rate, std_error, min_error, min_std, warning_level, drift_level):
    signal = error_rate + std_error
    min_signal = min_error + min_std
    if signal > min_signal + drift_level * min_std:
        return 2.0
    if signal > min_signal + warning_level * min_std:
        return 1.0
    return 0.0
